query:
mutation AddSectigoClm($apiUrl: String!, $tokenUrl: String!, $clientId: String!, $clientSecret: String!, $enabled: Boolean, $schedule: String!, $applications: [Int!]) {
  addSectigoClm(
    apiUrl: $apiUrl
    tokenUrl: $tokenUrl
    clientId: $clientId
    clientSecret: $clientSecret
    enabled: $enabled
    schedule: $schedule
    applications: $applications
  ) {
    status
    msg
    __typename
  }
}
